// File: /public/js/admin-startup-readiness.js
// Build 226 — actionable startup status cockpit with validated API loading and honest local recovery.
(() => {
  const LOCAL_KEY = 'dd_startup_readiness_unsynced_v1';
  const FALLBACK = [{"key": "backup_migrate_deploy", "phase": "foundation", "phase_label": "Foundation and deployment", "title": "Back up D1, apply the current migration, and deploy the complete build", "order": 10, "severity": "critical", "live": 1, "route": "/admin/deployment-preflight/", "external": "Cloudflare Dashboard → Workers & Pages → D1 and Pages deployments", "instructions": "1. Open Cloudflare D1 and create a production backup or export before changing the schema.\n2. Record the backup date, database name, and safe storage location in the evidence notes.\n3. Apply database_build225_startup_readiness_packaging_authority.sql or database_upgrade_current_pass.sql, but not both.\n4. Deploy the complete ZIP rather than selected files.\n5. Open Deployment Preflight and run every available check.\n6. Save the deployment URL, commit or deployment identifier, and the preflight result.\n7. Stop and restore the previous deployment if any critical migration or routing error appears.", "pass": "A recoverable D1 backup exists, the Build 225 migration is applied once, the complete deployment is live, and Deployment Preflight has no unresolved critical result."}, {"key": "production_bindings_secrets", "phase": "foundation", "phase_label": "Foundation and deployment", "title": "Verify production bindings, secrets, domains, and environment separation", "order": 20, "severity": "critical", "live": 1, "route": "/admin/deployment-preflight/", "external": "Cloudflare Pages project → Settings → Variables and Bindings; custom domains; D1/R2 bindings", "instructions": "1. Confirm the production Pages project is connected to the intended D1 database and R2 buckets.\n2. Confirm every required secret exists in Production, not only Preview.\n3. Check payment, email, OAuth, admin-bootstrap, analytics, and storage variables against CLOUDFLARE_ENVIRONMENT_CHECKLIST_DETAILED.md.\n4. Confirm preview/test credentials are not used in production and production credentials are not committed to the repository.\n5. Confirm devilndove.com and any www redirect resolve to the production deployment with valid HTTPS.\n6. Test one read and one safe write against each required binding.\n7. Record only variable names and test results; never paste secret values into evidence.", "pass": "The production domain, D1, R2, payment, email, and required application bindings are present in the correct environment and pass safe connectivity checks without exposing secrets."}, {"key": "login_logout_recovery", "phase": "access", "phase_label": "Access, security, and recovery", "title": "Prove production login, logout, session expiry, and password recovery", "order": 30, "severity": "critical", "live": 1, "route": "/login/", "external": "Production website and the configured transactional email provider", "instructions": "1. Open a private browser window and log in with a test administrator account.\n2. Confirm successful login redirects correctly and does not return a 500 error.\n3. Log out and verify protected pages and APIs are no longer accessible.\n4. Request a password reset from the public recovery page.\n5. Confirm the reset message arrives, the link can be used once, and an expired or reused link is rejected.\n6. Test Logout All Sessions and confirm an older browser session is invalidated.\n7. Leave a test session idle long enough to confirm expiry behaviour and a clear sign-in recovery path.\n8. Record browser, time, account role, and result without storing passwords or tokens.", "pass": "Login, logout, reset, one-time token use, session expiry, and logout-all work in production without 500 errors or continued access after invalidation."}, {"key": "role_authorization", "phase": "access", "phase_label": "Access, security, and recovery", "title": "Verify server-side authorization for destructive, financial, and approval actions", "order": 40, "severity": "critical", "live": 1, "route": "/admin/members/", "external": "Production admin APIs and role test accounts", "instructions": "1. Prepare an administrator account and at least one lower-privilege test account.\n2. Test permanent product deletion, inventory reversal, label approval, accounting export, member administration, and publication approval.\n3. Confirm the administrator can perform only the actions intended for that role.\n4. Call the same APIs while signed in as the lower role and confirm 401 or 403 responses.\n5. Confirm hiding a button is not the only protection; direct API calls must also be denied.\n6. Confirm every successful sensitive action creates an audit record with actor, target, time, and reason.\n7. Remove or disable temporary test accounts after the review.", "pass": "Every sensitive action is enforced on the server, lower roles receive 401/403, and successful actions are attributable in the audit history."}, {"key": "runtime_incident_fallback", "phase": "access", "phase_label": "Access, security, and recovery", "title": "Prove runtime incident capture and honest fallback behaviour", "order": 50, "severity": "high", "live": 1, "route": "/admin/runtime-incidents/", "external": "Production Pages Functions logs and runtime incident records", "instructions": "1. Use a safe test condition that causes a non-destructive optional API failure, such as an unavailable optional table in a preview environment.\n2. Confirm the API returns structured JSON with a useful status code and plain-language error.\n3. Confirm the browser shows a usable fallback or retry path without claiming a save, payment, export, or approval succeeded.\n4. Confirm the runtime incident includes scope, code, severity, user or request context, and a sanitized stack or detail.\n5. Restore the optional dependency and verify the normal path recovers.\n6. Review offline.html and low-bandwidth media fallbacks on a throttled connection.", "pass": "Expected failures are visible, sanitized, recoverable, and recorded; fallback states never present an uncompleted business action as successful."}, {"key": "launch_product_list", "phase": "catalog", "phase_label": "Catalog, product facts, and media", "title": "Choose a small opening-day product list and freeze its launch scope", "order": 60, "severity": "critical", "live": 0, "route": "/admin/products/", "external": "Internal operating decision", "instructions": "1. Select a deliberately small group of products that can be physically counted, photographed, packaged, and fulfilled now.\n2. Exclude experimental, incomplete, duplicate, content-only, or uncertain products from the launch group.\n3. Record the product IDs, names, SKUs, and intended sale channels.\n4. Confirm every selected item has an owner responsible for facts, media, inventory, packaging, and final review.\n5. Keep other products in Draft or Archived while the site opens.\n6. Revisit the launch group only through a deliberate review so the finish line does not keep moving.", "pass": "A finite opening-day product list is recorded, owned, and protected from unrelated draft work."}, {"key": "product_detail_gallery", "phase": "catalog", "phase_label": "Catalog, product facts, and media", "title": "Verify every launch product View link, detail page, and seven-image gallery", "order": 70, "severity": "critical", "live": 1, "route": "/shop/", "external": "Public shop and /api/product-detail?slug=<slug>", "instructions": "1. Open the public Shop in a private browser window.\n2. Select View on every launch product card.\n3. Confirm the URL contains the correct slug and the detail endpoint returns HTTP 200 with ok:true.\n4. Confirm name, price, description, SKU, availability, shipping information, and calls to action match the admin record.\n5. For products with seven approved images, confirm seven unique thumbnails appear and each changes the main image, alternative text, caption, and image counter.\n6. Confirm blocked or consent-needed images remain excluded for a documented reason.\n7. Test direct loading, browser refresh, copied link, mobile view, and the public catalog fallback.\n8. Record every product that returns fewer images or stale facts and correct it in Catalog Media or Products.", "pass": "Every launch product opens from its card, returns current facts, and displays all approved unique storefront images without broken routes or stale fallback content."}, {"key": "product_facts_preflight", "phase": "catalog", "phase_label": "Catalog, product facts, and media", "title": "Complete Product Release Preflight for every launch product", "order": 80, "severity": "critical", "live": 0, "route": "/admin/release-preflight/", "external": "Devil n Dove Product Release Preflight", "instructions": "1. Filter Product Release Preflight to the opening-day product list.\n2. Resolve required name, slug, SKU, price, category, description, quantity, dimensions, weight, shipping, tax, care, condition, and sale-channel facts.\n3. Confirm quantity pricing and set components where applicable.\n4. Resolve every blocking media, consent, packaging, content, or inventory warning.\n5. Open the public detail page after each important correction.\n6. Record any warning intentionally accepted, who accepted it, and why.\n7. Do not publish a product merely because a percentage score looks high; manually review the final buyer view.", "pass": "Every opening-day product is green for required preflight checks and has a final human review of the public page."}, {"key": "catalog_media_rights", "phase": "catalog", "phase_label": "Catalog, product facts, and media", "title": "Finish product media, rights, roles, alt text, and R2 delivery", "order": 90, "severity": "critical", "live": 1, "route": "/admin/catalog-media/", "external": "Catalog Media, R2 object delivery, and public product pages", "instructions": "1. Assign one featured image and up to six supporting images to each launch product.\n2. Set image role, display order, concise descriptive alt text, caption where useful, and public-use status.\n3. Confirm ownership or consent and keep blocked/consent-needed media out of public responses.\n4. Verify full, thumbnail, WebP, and AVIF derivatives where configured.\n5. Test image loading on a normal desktop connection and a throttled mobile connection.\n6. Confirm image URLs do not expose private object paths or require an expired signed URL for public catalog media.\n7. Replace every launch-product placeholder or broken image with approved real media.", "pass": "Every launch product has an approved featured image, supporting media where available, documented rights, useful alt text, and reliable public delivery."}, {"key": "pricing_quantity_sets", "phase": "commerce", "phase_label": "Pricing, inventory, and checkout", "title": "Verify base prices, quantity specials, sets, coupons, and gift-card interactions", "order": 100, "severity": "critical", "live": 1, "route": "/admin/products/", "external": "Public product detail, cart, checkout, and payment total", "instructions": "1. For each launch product, compare the stored base price with the public detail page, cart, checkout, and payment provider.\n2. Test every quantity breakpoint using the exact threshold, one below, and one above.\n3. Confirm the per-unit price never increases unexpectedly at a higher advertised tier.\n4. For sets, confirm component quantities and requested reserved-set quantity are correct.\n5. Test coupon and gift-card combinations only if those features are publicly displayed.\n6. Confirm discounts cannot reduce a price below an approved floor or create a negative total.\n7. Verify the server recalculates all totals and ignores browser-edited values.\n8. Record screenshots or order IDs for each scenario.", "pass": "Displayed and server-calculated prices, discounts, quantity tiers, sets, and final payment totals match approved business rules."}, {"key": "inventory_regular_exact_once", "phase": "commerce", "phase_label": "Pricing, inventory, and checkout", "title": "Prove exact-once inventory settlement for regular products", "order": 110, "severity": "critical", "live": 1, "route": "/admin/orders/", "external": "Production checkout, Stripe webhook events, orders, and inventory movements", "instructions": "1. Record the starting inventory of a safe test product.\n2. Complete one paid production order for one unit.\n3. Confirm inventory is consumed only after the approved payment event and exactly one movement is recorded.\n4. Replay or resend the same webhook event and confirm no second consumption occurs.\n5. Attempt a failed and an expired checkout and confirm no permanent consumption remains.\n6. Compare order quantity, inventory movement, on-hand quantity, and audit history.\n7. Use a compensating correction only through the reviewed inventory workflow if the test exposes a defect.", "pass": "A successful payment consumes the correct quantity once, retries are idempotent, and failed or expired payment attempts do not leave stock consumed."}, {"key": "inventory_sets_concurrency", "phase": "commerce", "phase_label": "Pricing, inventory, and checkout", "title": "Prove component-set reservation, zero availability, and final-unit concurrency", "order": 120, "severity": "critical", "live": 1, "route": "/admin/products/", "external": "Production set product, component products, simultaneous checkout sessions", "instructions": "1. Create or use a safe set with known component quantities and a small temporary stock level.\n2. Confirm the set availability equals the lowest whole number of complete component sets.\n3. Confirm reserved components reduce the individual component availability shown publicly.\n4. Reduce one component below the required quantity and confirm the set shows zero available.\n5. Restore stock through a reviewed movement, not a direct database edit.\n6. Open two private browser sessions and attempt to buy the final available set or final one-of-a-kind item at nearly the same time.\n7. Confirm only one checkout can settle and the other receives a clear unavailable result.\n8. Confirm cancellation/refund restores both set and component availability exactly once.", "pass": "Set availability is component-limited, reservations are visible, zero availability is enforced, and simultaneous final-unit attempts cannot oversell."}, {"key": "purchase_lots_costs", "phase": "commerce", "phase_label": "Pricing, inventory, and checkout", "title": "Reconcile tools, supplies, purchase lots, dates, and actual costs", "order": 130, "severity": "high", "live": 0, "route": "/admin/inventory-operations/", "external": "Amazon order history, supplier invoices, and physical stock count", "instructions": "1. Open Tools & Supplies and choose Lots for each launch material.\n2. Enter each separate purchase with purchase/received date, supplier, order number, ASIN or supplier SKU, quantity, unit cost, allocated tax/shipping, storage location, and expiry where applicable.\n3. Keep goat milk bases, oils, mica, coloured bases, fragrance, packaging, and other batches separate when traceability matters.\n4. Compare total lot remaining with the main on-hand quantity.\n5. Physically count the material before applying a lot total to main inventory.\n6. Use the review and APPLY LOT TOTAL confirmation rather than editing D1 directly.\n7. Record quarantine, expiry, return, or consumed status accurately.\n8. Verify project and product costing uses reviewed costs rather than a stale default.", "pass": "Every launch material has traceable purchase evidence, physical quantity, lot status, and a reviewed cost suitable for margin calculation."}, {"key": "tax_scenarios", "phase": "commerce", "phase_label": "Pricing, inventory, and checkout", "title": "Verify Canadian tax scenarios and refund tax calculations", "order": 140, "severity": "critical", "live": 1, "route": "/checkout/", "external": "Production checkout, payment provider, and accountant-reviewed tax settings", "instructions": "1. Confirm the business tax-registration status and effective date with the owner/accountant.\n2. Test an Ontario shipping address and every other province or territory the store accepts.\n3. Test local pickup if enabled.\n4. Confirm tax treatment for physical goods, digital items, shipping charges, discounts, gift cards, and refunds.\n5. Compare the public checkout total, payment-provider amount, stored order tax, and accounting journal.\n6. Confirm unsupported destinations are rejected before payment.\n7. Save scenario evidence and the business rule used; do not rely only on a browser display.", "pass": "Every accepted destination and product type produces the reviewed tax result, and refunds reverse the correct tax amount."}, {"key": "shipping_pickup", "phase": "commerce", "phase_label": "Pricing, inventory, and checkout", "title": "Verify shipping destinations, rates, pickup, packaging, and fulfilment promises", "order": 150, "severity": "critical", "live": 1, "route": "/pickup/", "external": "Checkout, carrier or shipping-rate source, packing materials, and public policies", "instructions": "1. List the destinations the business can actually fulfil at launch.\n2. Test Ontario, another supported province, PO box handling, and US/international only when intentionally enabled.\n3. Confirm package weight and dimensions for each launch-product family.\n4. Compare checkout rates with the expected carrier or flat-rate policy.\n5. Test local pickup instructions, pickup timing, contact details, and tax treatment.\n6. Confirm free-shipping thresholds and surcharges cannot be bypassed through quantity or discount combinations.\n7. Perform one physical pack test and verify the product is protected by the materials included in its cost.\n8. Ensure policy text matches actual operating practice.", "pass": "Every accepted address can be fulfilled at the displayed cost and timeframe, pickup instructions are accurate, and physical packaging protects the product."}, {"key": "stripe_live_webhook", "phase": "payments", "phase_label": "Payments, refunds, and financial controls", "title": "Complete Stripe live capture, signed webhook, and idempotency proof", "order": 160, "severity": "critical", "live": 1, "route": "/admin/webhook-events/", "external": "Stripe Dashboard → Developers → Webhooks and production payment settings", "instructions": "1. Confirm live Stripe keys and the production webhook signing secret are stored in Production secrets.\n2. Confirm the public webhook endpoint and subscribed event types match the application.\n3. Place one low-value real order with an owner-controlled payment method.\n4. Confirm the payment amount, currency, order ID, customer details, and settlement status.\n5. Confirm the webhook signature is verified before any state change.\n6. Resend the same event and confirm the event ID is not applied twice.\n7. Test a failed payment, expired checkout, and customer cancellation.\n8. Record Stripe event IDs and order IDs, never secret values or full card data.", "pass": "A live payment settles once, its signed webhook is verified, duplicate delivery has no duplicate effect, and failed/cancelled sessions remain recoverable."}, {"key": "refund_restore", "phase": "payments", "phase_label": "Payments, refunds, and financial controls", "title": "Prove cancellation, partial/full refund, and inventory restoration", "order": 170, "severity": "critical", "live": 1, "route": "/admin/orders/", "external": "Order management, payment provider, inventory movements, and accounting records", "instructions": "1. Use a separate paid rehearsal order after the successful-payment test.\n2. Cancel before fulfilment and confirm the order status, payment state, and inventory restoration.\n3. Test a full refund and, if supported publicly, a partial refund.\n4. Confirm each refund creates one provider action, one order history event, one inventory restoration where appropriate, and balanced accounting entries.\n5. Replay the refund webhook and confirm no second restoration or refund record occurs.\n6. Confirm non-restockable or partially fulfilled items require an explicit reviewed decision.\n7. Check the customer-facing refund communication.", "pass": "Cancellation and refund actions are idempotent, financially traceable, communicate clearly, and restore only the inventory that should return to sale."}, {"key": "paypal_visibility", "phase": "payments", "phase_label": "Payments, refunds, and financial controls", "title": "Make PayPal fully operational or completely hide it", "order": 180, "severity": "critical", "live": 1, "route": "/checkout/", "external": "PayPal developer/live account and production callback settings", "instructions": "1. Inspect checkout, footer, payment options, and documentation for PayPal references.\n2. If live credentials, callbacks, capture, cancellation, webhook, and refund paths are not proven, remove or hide PayPal from all public surfaces.\n3. If PayPal will launch, use a low-value owner-controlled transaction to test approval, capture, cancellation, webhook retry, and refund.\n4. Confirm order and inventory effects match the Stripe workflow and remain idempotent.\n5. Record the explicit business decision and date.", "pass": "Customers either receive a completely working PayPal option or see no PayPal option or promise anywhere on the live site."}, {"key": "accounting_tax_reporting", "phase": "payments", "phase_label": "Payments, refunds, and financial controls", "title": "Verify bookkeeping, payment application, HST/GST review, and export controls", "order": 190, "severity": "high", "live": 0, "route": "/admin/accounting/", "external": "Accountant-reviewed chart of accounts, tax settings, and export process", "instructions": "1. Confirm sales, tax, shipping, discounts, payment fees, refunds, inventory, cost of goods, and gift-card liabilities map to the intended accounts.\n2. Confirm paid orders can be applied to receivables and provider settlements without duplicate journals.\n3. Review HST/GST reporting fields and opening balances with the accountant.\n4. Test an accountant export with a safe date range and confirm lower roles cannot run it.\n5. Confirm month-end lock/reopen controls or document the temporary manual procedure.\n6. Record unresolved accounting limitations in the operating checklist before launch volume increases.", "pass": "Opening transactions can be reconciled and exported accurately, sensitive exports are authorized, and any temporary manual accounting controls are documented."}, {"key": "transactional_email", "phase": "communications", "phase_label": "Customer communication and policies", "title": "Verify every required transactional email and failure path", "order": 200, "severity": "critical", "live": 1, "route": "/admin/live-ops-followthrough/", "external": "Configured email provider, Gmail, Outlook, and mobile inboxes", "instructions": "1. Test registration or welcome, password reset, order confirmation, payment receipt, cancellation, refund, fulfilment/shipping, pickup, and review request when enabled.\n2. Send only to owner-controlled test addresses.\n3. Check Gmail, Outlook, and a mobile mail application.\n4. Confirm sender name, reply-to, domain authentication, links, order facts, plain-text fallback, and unsubscribe requirements for non-transactional mail.\n5. Trigger a safe provider failure and confirm it is visible in logs or an admin retry queue.\n6. Confirm no secret, internal note, or unrelated customer data appears in the message.\n7. Save provider message IDs or screenshots as evidence.", "pass": "Essential messages arrive with correct facts and links, failures are observable, and a safe resend or support path exists."}, {"key": "customer_support_contact", "phase": "communications", "phase_label": "Customer communication and policies", "title": "Verify contact, custom request, order-help, and customer-service response paths", "order": 210, "severity": "high", "live": 1, "route": "/contact/", "external": "Public contact/custom-request forms and owner-controlled inbox", "instructions": "1. Submit the public contact form and any enabled custom-request form from a private browser.\n2. Confirm required consent, spam protection, validation, acknowledgement, and admin visibility.\n3. Ask a product, shipping, pickup, return, and custom-order question using test data.\n4. Confirm the message reaches the correct owner inbox or admin queue with a useful reference.\n5. Verify a customer can find order-help instructions without entering admin areas.\n6. Confirm response-time promises are realistic and consistent with policy pages.\n7. Delete test personal data after verification where appropriate.", "pass": "Customers can reach the business, receive acknowledgement, and obtain order/product help through monitored channels with realistic response expectations."}, {"key": "policies_legal", "phase": "communications", "phase_label": "Customer communication and policies", "title": "Review privacy, terms, shipping, pickup, returns, refunds, and custom-work policies", "order": 220, "severity": "critical", "live": 0, "route": "/terms/", "external": "Public footer, checkout, product pages, and owner/legal review", "instructions": "1. Open every public policy from the footer and checkout.\n2. Confirm business name, contact method, effective date, jurisdiction, shipping destinations, pickup rules, cancellation, return, refund, damaged-item, custom/personalized, digital, and privacy wording.\n3. Make sure policies describe actual operations and do not promise unsupported delivery times or return rights.\n4. Confirm product pages link to the policy information customers need before payment.\n5. Verify privacy/data-deletion instructions reflect the data actually collected by forms, analytics, accounts, and payment providers.\n6. Review special conditions for one-of-a-kind, vintage, made-to-order, and cosmetic products.\n7. Record who reviewed the final policy set and when.", "pass": "All customer-facing policies are findable before payment, internally consistent, dated, and aligned with the way the business will actually operate."}, {"key": "soap_formula_ingredients", "phase": "packaging", "phase_label": "Soap, packaging, and regulatory readiness", "title": "Verify each soap formula, INCI order, bilingual identity, warnings, and claims", "order": 230, "severity": "critical", "live": 0, "route": "/admin/packaging/soap-labels/", "external": "Verified recipe/formula records, supplier documents, bilingual review, and applicable cosmetic requirements", "instructions": "1. Link the soap label project to the intended finished soap product and verified recipe or formula source.\n2. Enter ingredients in reviewed INCI order rather than copying supplier marketing bullets.\n3. Complete matched English and French product identity, ingredient display rows, warnings, dealer/address, consumer contact, Canadian-origin wording, and metric net quantity.\n4. Review fragrance, colourant, allergen, and claim obligations that apply to the final formula.\n5. Confirm every displayed claim has an internal approval note and factual support.\n6. Compare the structured rows against the batch record and physical product.\n7. Lock the reviewed source facts before creating the final label version.", "pass": "The label content reflects the actual formula and reviewed bilingual/legal facts; no ingredient or claim is inferred from artwork or supplier advertising."}, {"key": "soap_print_proof", "phase": "packaging", "phase_label": "Soap, packaging, and regulatory readiness", "title": "Generate, measure, wrap-test, approve, and archive each soap label", "order": 240, "severity": "critical", "live": 0, "route": "/admin/packaging/soap-labels/", "external": "100% physical printer proof and PACKAGING_STUDIO.md", "instructions": "1. Use PACKAGING_STUDIO.md as the single packaging source of truth.\n2. Generate the continuous ribbon from structured records and save a review version.\n3. Print at 100% with browser/page scaling disabled.\n4. Measure strip width, band height, front oval, rear seal, bleed, and safe-area result.\n5. Test both the photo-fit and true-50-mm profile if the final physical geometry is not yet chosen.\n6. Wrap the actual soap and inspect front centring, folds, overlap/glue, ingredient legibility, French text, claims, net weight, barcode/batch zones, and colour.\n7. Upload or link a proof photo, record printer/paper, and mark fit, legibility, and overlap separately.\n8. Approve and archive only the version that passed; supersede rather than silently overwrite an approved label.", "pass": "Each launch soap has a saved, physically measured, wrapped, passed, approved, and archived label version linked to its exact structured source data."}, {"key": "health_canada_notification", "phase": "packaging", "phase_label": "Soap, packaging, and regulatory readiness", "title": "Prepare Health Canada cosmetic notification and change control", "order": 250, "severity": "critical", "live": 1, "route": "/admin/startup-readiness/", "external": "Health Canada Cosmetic Notification Form and official guidance", "instructions": "1. Determine which launch products are cosmetics and identify the responsible manufacturer or importer.\n2. Prepare product identity, intended use, company/contact, first-sale date, formula ingredients, concentration ranges, and other required notification information.\n3. Submit the Cosmetic Notification Form within the applicable period after first sale; current official guidance states within 10 days after first sale in Canada.\n4. Save the submission confirmation or reference outside the public website and record a safe evidence pointer here.\n5. Create a change-control rule for name, formula, concentration, company, contact, or other reportable changes.\n6. Review the Cosmetic Ingredient Hotlist and other applicable official requirements before release.\n7. Do not treat an app-generated label or notification record as legal approval.", "pass": "Every applicable cosmetic has an owner, prepared/submitted notification evidence, and a documented process for later formula or business-detail changes."}, {"key": "packaging_prepress_boundary", "phase": "packaging", "phase_label": "Soap, packaging, and regulatory readiness", "title": "Confirm the packaging export is suitable for the chosen printer and production method", "order": 260, "severity": "high", "live": 0, "route": "/admin/packaging-studio/", "external": "Chosen printer, paper/stock, cutter, colour profile, and production proof", "instructions": "1. Confirm whether the printer accepts SVG, browser-generated PDF, or requires a prepress PDF with crop/bleed boxes and embedded/outlined fonts.\n2. Verify the exact media size, bleed, safe area, crop marks, colour mode/profile, and no-scaling setting.\n3. Confirm the rose and icon assets remain sharp and licensed/owned for production use.\n4. Print a calibration ruler and compare measured output to the design dimensions.\n5. Record printer, paper, driver, scaling, colour, and cutting settings.\n6. Keep browser Print/Save PDF labelled as preparation until the chosen printer accepts it as final production output.\n7. Archive the source SVG, delivered file, checksum, and proof result.", "pass": "The chosen printer and material reproduce the approved dimensions, type, colour, bleed, and cut safely using an archived export and documented settings."}, {"key": "analytics_consent", "phase": "discovery", "phase_label": "Search, analytics, accessibility, and quality", "title": "Verify analytics, consent, privacy boundaries, and commerce event accuracy", "order": 270, "severity": "high", "live": 1, "route": "/admin/site-analytics/", "external": "GA4 or configured analytics property and browser developer tools", "instructions": "1. Confirm the production analytics identifier is loaded once on public pages and not duplicated by multiple scripts.\n2. Test page_view, view_item, add_to_cart, begin_checkout, purchase, refund, contact, and custom-request events that are actually enabled.\n3. Confirm transaction IDs prevent duplicate purchase events after refresh.\n4. Verify no secret, password, payment detail, private admin note, or unnecessary personal data is sent.\n5. Test consent or privacy controls required by the chosen analytics setup.\n6. Exclude admin and preview traffic where practical.\n7. Compare one test order with analytics and the stored order.", "pass": "Public and commerce activity is observable once, privacy boundaries are respected, and analytics values can be reconciled to a test transaction."}, {"key": "search_console_indexing", "phase": "discovery", "phase_label": "Search, analytics, accessibility, and quality", "title": "Verify sitemap, robots, canonical URLs, Search Console, and index coverage", "order": 280, "severity": "high", "live": 1, "route": "/sitemap.xml", "external": "Google Search Console for devilndove.com", "instructions": "1. Open robots.txt and sitemap.xml on the production domain and confirm both load successfully.\n2. Confirm the sitemap contains only intended canonical public URLs and excludes admin/private pages.\n3. Verify the domain property in Search Console and submit the sitemap.\n4. Inspect the home page, shop, one category/local page, and several product-detail URLs.\n5. Confirm canonical URLs use the production domain and query-based product pages resolve consistently.\n6. Review index coverage, mobile usability, structured-data reports, manual actions, and security issues.\n7. Record important indexing problems as separate work items rather than repeatedly changing titles without evidence.", "pass": "Search Console owns the production property, the sitemap/canonical system is correct, and representative public pages are crawlable without critical index or security errors."}, {"key": "google_business_profile", "phase": "discovery", "phase_label": "Search, analytics, accessibility, and quality", "title": "Complete and verify Google Business Profile and local-business consistency", "order": 290, "severity": "high", "live": 1, "route": "/contact/", "external": "Google Business Profile for Devil n Dove", "instructions": "1. Confirm the profile name, primary/secondary categories, phone, website, service or pickup area, hours, special hours, description, products/services, and photos are accurate.\n2. Keep address visibility consistent with how customers actually visit or receive products.\n3. Compare business name, phone, website, and locality wording with the website and major directory profiles.\n4. Add current real photos and respond to legitimate reviews without incentives that violate platform rules.\n5. Use local wording only where it truthfully reflects pickup, service, market, or delivery reach.\n6. Record monthly evidence and any profile correction task.\n7. Do not promise or report a guaranteed first-page position; monitor relevance, distance, and prominence over time.", "pass": "The Business Profile is complete, accurate, consistent with the website, actively maintained, and supported by real local proof and customer trust."}, {"key": "seo_page_quality", "phase": "discovery", "phase_label": "Search, analytics, accessibility, and quality", "title": "Run the public SEO, title, H1, structured-data, image, and internal-link audit", "order": 300, "severity": "high", "live": 1, "route": "/admin/local-seo-review/", "external": "Production public pages, Google rich-result tools, and Search Console", "instructions": "1. Scan every indexable HTML page for one and only one H1, a distinctive title, useful meta description, canonical URL, robots directive, and meaningful visible introduction.\n2. Make the main title visually unambiguous; avoid multiple headings with equal title prominence.\n3. Use descriptive buyer language in titles, headings, product facts, image alt text, and internal links without stuffing locations or keywords.\n4. Validate Organization/LocalBusiness, Breadcrumb, Product, Offer, image, and other applicable structured data against visible facts.\n5. Confirm Product schema includes the approved gallery images, current price, currency, availability, SKU, and canonical offer URL.\n6. Check crawlable internal links to important shop, category, policy, contact, story, and local relevance pages.\n7. Review duplicate/thin pages and redirect or noindex where appropriate.\n8. Record before/after evidence for changes rather than guessing from rankings.", "pass": "All indexable pages pass the one-H1 and metadata audit, structured data matches visible facts, and important pages are discoverable through descriptive crawlable links."}, {"key": "mobile_accessibility_performance", "phase": "discovery", "phase_label": "Search, analytics, accessibility, and quality", "title": "Complete real-device mobile, keyboard, accessibility, and performance testing", "order": 310, "severity": "critical", "live": 1, "route": "/admin/post-deploy-smoke-tests/", "external": "Real phones/tablet/desktop, Lighthouse/PageSpeed, keyboard, and screen-reader checks", "instructions": "1. Test a narrow phone, large phone, tablet, laptop, and large desktop in portrait and landscape where relevant.\n2. Complete navigation, product view/gallery, cart, checkout, login, password reset, contact, and critical admin workflows.\n3. Confirm touch targets, sticky actions, form labels, validation, focus visibility, keyboard order, dialogs, tables, and horizontal overflow.\n4. Check colour contrast and text readability in dark/light surfaces used by the site.\n5. Test with images disabled or a slow connection and confirm useful fallback content.\n6. Run Lighthouse/PageSpeed on home, shop, product detail, contact, and an important local/content page on mobile and desktop.\n7. Fix critical accessibility errors and layout overlap before launch; document lower-priority performance work.\n8. Re-run after CSS or image changes.", "pass": "Critical customer journeys work on target devices and keyboard, no blocking accessibility or overlap defect remains, and performance evidence is recorded."}, {"key": "social_oauth_visibility", "phase": "discovery", "phase_label": "Search, analytics, accessibility, and quality", "title": "Keep social publishing controls review-first until provider OAuth is approved", "order": 320, "severity": "medium", "live": 1, "route": "/admin/social-hub/", "external": "Meta, Pinterest, YouTube, TikTok, and other configured provider developer consoles", "instructions": "1. List each social provider shown in the admin or public interface.\n2. Confirm callback URLs, privacy/data-deletion pages, scopes, app review, tokens, and page/account identifiers are approved and current.\n3. Keep automatic publishing disabled for providers that are not completely connected.\n4. Test draft generation, deliberate approval, one safe publish, provider response, and analytics link tracking separately.\n5. Confirm failure or token expiry leaves content in review rather than falsely marked published.\n6. Hide unfinished public promises or buttons; social OAuth is not a blocker to selling when publishing remains manual.", "pass": "Unapproved providers remain disabled and honestly labelled; any enabled provider publishes only after deliberate review with observable success/failure evidence."}, {"key": "backup_restore_rehearsal", "phase": "operations", "phase_label": "Recovery, fulfilment, and controlled opening", "title": "Rehearse D1, R2, deployment, and configuration recovery", "order": 330, "severity": "critical", "live": 1, "route": "/admin/deployment-preflight/", "external": "Cloudflare D1 backups/exports, R2, Pages deployments, and secure configuration records", "instructions": "1. Create a test or copied environment that can be restored without risking production customer data.\n2. Restore a recent D1 backup and verify users, products, inventory, orders, packaging, and readiness records.\n3. Verify R2 object inventory and restore or re-link a safe test media object.\n4. Roll back to a previous Pages deployment, run smoke tests, then return to the current deployment.\n5. Confirm required variable and binding names are documented outside the code without storing secret values in the repository.\n6. Measure recovery time and record the operator steps that were confusing or missing.\n7. Update the recovery guide after the rehearsal.", "pass": "A tested operator can restore database, media, deployment, and required configuration within an acceptable time using documented steps."}, {"key": "paid_order_fulfilment_rehearsal", "phase": "operations", "phase_label": "Recovery, fulfilment, and controlled opening", "title": "Complete a real paid order from product view through fulfilment", "order": 340, "severity": "critical", "live": 1, "route": "/admin/orders/", "external": "Public store, payment provider, email, packaging, pickup/shipping, inventory, and accounting", "instructions": "1. Use a launch product and an owner-controlled customer identity/payment method.\n2. Start from the public Shop, inspect the product gallery/facts, add to cart, and complete checkout.\n3. Confirm payment, webhook, order, inventory, tax, shipping/pickup, email, and accounting records.\n4. Pick the physical item, verify lot/batch where relevant, package it with the approved label/materials, and mark fulfilment.\n5. Confirm the customer receives the correct fulfilment or pickup message.\n6. Compare actual labour, packaging, shipping, provider fee, and margin with the stored assumptions.\n7. Save order ID, timestamps, and issues; never store full payment credentials.", "pass": "One real order completes end to end with correct product, money, stock, communication, packaging, fulfilment, and reconciliable records."}, {"key": "separate_refund_rehearsal", "phase": "operations", "phase_label": "Recovery, fulfilment, and controlled opening", "title": "Complete a separate cancellation/refund rehearsal and customer recovery", "order": 350, "severity": "critical", "live": 1, "route": "/admin/orders/", "external": "Production payment, order, inventory, email, and accounting systems", "instructions": "1. Use a different low-value owner-controlled rehearsal order so the paid-order proof remains intact.\n2. Test the actual cancellation/refund workflow an operator will use.\n3. Confirm provider refund, order history, customer email, inventory decision, tax reversal, fee treatment, and accounting entries.\n4. Confirm the item is returned to sellable stock only after physical/operational review where required.\n5. Replay the provider event and confirm the recovery action remains idempotent.\n6. Document the customer-service wording and escalation path for a failed automated step.", "pass": "A separate refund/cancellation can be completed safely, communicated clearly, reconciled, and repeated webhook delivery cannot duplicate its effects."}, {"key": "launch_monitoring_ownership", "phase": "operations", "phase_label": "Recovery, fulfilment, and controlled opening", "title": "Assign launch-day ownership, monitoring, support, and stop conditions", "order": 360, "severity": "critical", "live": 0, "route": "/admin/startup-readiness/", "external": "Internal launch operating plan", "instructions": "1. Name the person responsible for orders, payments, inventory, email, customer messages, site incidents, and public updates during opening.\n2. Define the hours the store will be actively monitored during the first days.\n3. Write stop conditions for payment mismatch, oversell, repeated 500 errors, lost email, wrong tax, broken fulfilment, or unsafe product/label concern.\n4. Record how to hide checkout, archive a product, roll back a deployment, contact customers, and preserve evidence.\n5. Confirm the owner can access the required dashboards and recovery instructions from a phone.\n6. Prepare a short daily review of orders, incidents, inventory, refunds, and customer questions.", "pass": "Each launch responsibility has an owner and the team has clear monitoring, escalation, rollback, and temporary-stop instructions."}, {"key": "controlled_opening", "phase": "operations", "phase_label": "Recovery, fulfilment, and controlled opening", "title": "Open with controlled stock, limited products, and a reversible rollout", "order": 370, "severity": "critical", "live": 1, "route": "/admin/startup-readiness/", "external": "Production store and launch operating decision", "instructions": "1. Confirm every critical readiness item is Complete or has a formally justified Not Applicable decision.\n2. Keep the opening-day product list small and inventory conservative.\n3. Open to a limited audience or quiet public release before paid promotion.\n4. Monitor the first orders in real time and compare every system record.\n5. Pause sales immediately if a stop condition is reached.\n6. Add products and automation gradually only after the core order, inventory, email, refund, and fulfilment paths remain stable.\n7. Record the opening time, product count, owner on duty, and first review time.", "pass": "The store opens through a monitored, reversible, low-risk release with no unresolved critical blocker and a clear pause/rollback path."}];
  const state = { data:null, filters:{search:'',status:'open',severity:'all',phase:'all'}, local:readLocal(), filterTimer:null };
  const id = (name) => document.getElementById(name);
  const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (ch) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  function readLocal() { try { const value=JSON.parse(localStorage.getItem(LOCAL_KEY)||'{}'); return value&&typeof value==='object'?value:{}; } catch { return {}; } }
  function writeLocal() { localStorage.setItem(LOCAL_KEY,JSON.stringify(state.local)); }
  function message(text='',kind='') { const node=id('startupReadinessMessage'); if(!node)return; node.hidden=!text; node.textContent=text; node.className=`card startup-message ${kind==='error'?'is-error':kind==='success'?'is-success':kind==='warning'?'is-warning':''}`; }
  function human(value) { const map={not_started:'Not started',in_progress:'In progress',blocked:'Blocked',needs_review:'Needs review',passed:'Complete',failed:'Failed',not_applicable:'Not applicable'}; return map[value]||String(value||'Unknown').replace(/_/g,' '); }
  function closed(status) { return ['passed','not_applicable'].includes(status); }
  function fallbackData() { const rows=FALLBACK.map((x)=>({item_key:x.key,phase_key:x.phase,phase_label:x.phase_label,item_title:x.title,sort_order:x.order,blocker_severity:x.severity,requires_live_binding:x.live,target_route:x.route,external_location:x.external,instructions_markdown:x.instructions,pass_condition:x.pass,item_status:'not_started',owner_name:'',due_date:'',evidence_url:'',evidence_notes:'',blocked_reason:''})); return {ok:true,build:'226',degraded:true,backend_warning:'The startup API could not be reached. Instructions are available, but status changes are stored only in this browser until successfully synchronized.',items:rows,recent_history:[],stats:stats(rows),markdown:''}; }
  function applyLocal(data) { const rows=(data.items||[]).map((row)=>state.local[row.item_key]?{...row,...state.local[row.item_key],local_unsynced:true}:row); return {...data,items:rows,stats:stats(rows)}; }
  function stats(rows) { const total=rows.length, complete=rows.filter((r)=>closed(r.item_status)).length; const criticalOpen=rows.filter((r)=>r.blocker_severity==='critical'&&!closed(r.item_status)).length; const highOpen=rows.filter((r)=>r.blocker_severity==='high'&&!closed(r.item_status)).length; const blocked=rows.filter((r)=>r.item_status==='blocked').length; return {total,complete,open:total-complete,critical_open:criticalOpen,high_open:highOpen,blocked,in_progress:rows.filter((r)=>r.item_status==='in_progress').length,completion_percent:total?Math.round(complete/total*100):0,launch_state:!criticalOpen&&!highOpen&&complete===total?'ready':!criticalOpen&&!highOpen?'ready_for_final_rehearsal':!criticalOpen?'controlled_launch_review':'not_ready'}; }
  function validItem(row) { return !!(row&&typeof row==='object'&&String(row.item_key||'').trim()&&String(row.item_title||'').trim()); }
  function validateData(payload) { const data=payload&&Array.isArray(payload.items)?payload:payload?.data&&Array.isArray(payload.data.items)?payload.data:null; const expected=Math.max(1,Number(data?.expected_total)||37); const unique=data?new Set(data.items.map((row)=>String(row?.item_key||''))).size:0; if(!data||data.items.length!==expected||unique!==expected||!data.items.every(validItem)){ const error=new Error(`The startup service returned an incomplete readiness list (${data?.items?.length||0} of ${expected}). The built-in 37-gate guide is shown until the database service is available.`); error.status=502; throw error; } return data; }
  async function readResponse(response) { const raw=await response.text(); let data=null; try{data=raw?JSON.parse(raw):null;}catch{ const error=new Error('The startup service returned a webpage instead of readiness data. The built-in 37-gate guide is shown until the API deployment is corrected.'); error.status=response.ok?502:response.status; throw error; } if(!response.ok||data?.ok===false){ const error=new Error(data?.error||`Startup readiness request failed (${response.status}).`); error.status=response.status; throw error; } return validateData(data); }
  async function api(payload=null) { return readResponse(await DDAuth.apiFetch('/api/admin/startup-readiness',payload?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}:undefined)); }
  function steps(markdown) { const lines=String(markdown||'').split(/\n+/).map((line)=>line.trim()).filter(Boolean); const numbered=lines.every((line)=>/^\d+\.\s/.test(line)); if(numbered)return `<ol>${lines.map((line)=>`<li>${esc(line.replace(/^\d+\.\s*/,''))}</li>`).join('')}</ol>`; return `<p>${lines.map(esc).join('<br>')}</p>`; }
  function statusOptions(selected) { return ['not_started','in_progress','blocked','needs_review','passed','failed','not_applicable'].map((value)=>`<option value="${value}" ${value===selected?'selected':''}>${human(value)}</option>`).join(''); }
  function phaseOptions(rows) { const phases=[...new Map(rows.map((r)=>[r.phase_key,r.phase_label])).entries()]; return `<option value="all">All sections</option>${phases.map(([key,label])=>`<option value="${esc(key)}">${esc(label)}</option>`).join('')}`; }
  function filtered(rows) { const q=state.filters.search.toLowerCase(); return rows.filter((r)=>{ if(q&&!`${r.item_title} ${r.phase_label} ${r.instructions_markdown} ${r.owner_name||''}`.toLowerCase().includes(q))return false; if(state.filters.phase!=='all'&&r.phase_key!==state.filters.phase)return false; if(state.filters.severity!=='all'&&r.blocker_severity!==state.filters.severity)return false; if(state.filters.status==='open'&&closed(r.item_status))return false; if(state.filters.status!=='all'&&state.filters.status!=='open'&&r.item_status!==state.filters.status)return false; return true; }); }
  function readinessLabel(stats) { const map={not_ready:'Not ready — critical blockers remain',controlled_launch_review:'Critical gates closed; high-priority review remains',ready_for_final_rehearsal:'Ready for final rehearsals',ready:'All tracked gates complete'}; return map[stats.launch_state]||human(stats.launch_state); }
  function metric(label,value,extra='') { return `<article class="startup-metric"><span>${esc(label)}</span><strong>${esc(value)}</strong>${extra?`<small>${esc(extra)}</small>`:''}</article>`; }
  function card(row) { const local=row.local_unsynced?'<span class="startup-local-flag">Unsynced browser change</span>':''; const route=row.target_route?`<a class="btn small" href="${esc(row.target_route)}">Open page</a>`:''; return `<article class="card startup-item severity-${esc(row.blocker_severity)} status-${esc(row.item_status)}" data-key="${esc(row.item_key)}">
    <header class="startup-item-head"><div><div class="startup-kicker"><span>#${Number(row.sort_order||0)}</span><span>${esc(row.phase_label)}</span><span class="severity-badge">${esc(row.blocker_severity)}</span>${row.requires_live_binding?'<span>Production test</span>':''}${local}</div><h3>${esc(row.item_title)}</h3></div><span class="status-pill status-${esc(row.item_status)}">${esc(human(row.item_status))}</span></header>
    <div class="startup-locations">${route}${row.external_location?`<span><strong>External location:</strong> ${esc(row.external_location)}</span>`:''}</div>
    <details ${row.item_status==='blocked'?'open':''}><summary>Detailed instructions and pass condition</summary><div class="startup-steps">${steps(row.instructions_markdown)}</div><p class="startup-pass"><strong>Pass condition:</strong> ${esc(row.pass_condition)}</p></details>
    <form class="startup-item-form">
      <div class="startup-form-grid"><label><span>Status</span><select class="input" name="item_status">${statusOptions(row.item_status)}</select></label><label><span>Owner</span><input class="input" name="owner_name" maxlength="180" value="${esc(row.owner_name||'')}" placeholder="Person responsible"/></label><label><span>Due date</span><input class="input" name="due_date" type="date" value="${esc(row.due_date||'')}"/></label><label><span>Evidence link</span><input class="input" name="evidence_url" maxlength="1000" value="${esc(row.evidence_url||'')}" placeholder="/admin/... or https://..."/></label></div>
      <label><span>Evidence and completion notes</span><textarea class="input" name="evidence_notes" rows="3" maxlength="5000" placeholder="What was tested, what happened, and where the proof is stored">${esc(row.evidence_notes||'')}</textarea></label>
      <label class="blocked-field" ${row.item_status==='blocked'?'':'hidden'}><span>Why this is blocked</span><textarea class="input" name="blocked_reason" rows="2" maxlength="2000" placeholder="State the exact dependency or failure">${esc(row.blocked_reason||'')}</textarea></label>
      <div class="startup-actions"><button class="btn primary" type="submit">Save status</button><button class="btn success" type="button" data-complete>Mark complete</button><button class="btn" type="button" data-reopen>Reopen</button></div>
    </form>
    ${row.completed_at?`<p class="small">Completed: ${esc(row.completed_at)}</p>`:''}
  </article>`; }
  function render() { const data=state.data||fallbackData(); const rows=data.items||[]; const st=data.stats||stats(rows); const shown=filtered(rows); const host=id('startupReadinessMount'); if(!host)return; host.innerHTML=`
    <section class="card startup-overview"><div><p class="eyebrow">Build ${esc(data.build||'226')} • Database-backed launch gates</p><h2>${esc(readinessLabel(st))}</h2><p>Status, owner, due date, evidence, and history are stored in D1. A Complete or Not Applicable decision requires evidence notes or a link.</p></div><div class="startup-overview-actions"><button class="btn" id="startupRefresh" type="button">Refresh list</button><button class="btn" id="startupExport" type="button">Download status report</button>${Object.keys(state.local).length?'<button class="btn warning" id="startupSync" type="button">Sync browser changes</button>':''}</div></section>
    ${data.degraded?`<section class="card startup-degraded"><strong>Degraded mode</strong><p>${esc(data.backend_warning||'D1 status is unavailable.')}</p></section>`:''}
    <section class="startup-progress-card card"><div><strong>${st.completion_percent}% complete</strong><span>${st.complete} of ${st.total} gates closed</span></div><div class="startup-progress-track" aria-label="${st.completion_percent} percent complete"><span style="width:${st.completion_percent}%"></span></div></section>
    <section class="startup-metric-grid">${metric('Critical open',st.critical_open)}${metric('High open',st.high_open)}${metric('Blocked',st.blocked)}${metric('In progress',st.in_progress)}${metric('Complete',st.complete)}${metric('Showing',shown.length,`of ${st.total}`)}</section>
    <section class="card startup-filter-bar"><label><span>Search</span><input class="input" id="startupSearch" type="search" value="${esc(state.filters.search)}" placeholder="Item, section, instruction, or owner"/></label><label><span>Status</span><select class="input" id="startupStatus"><option value="open">Open only</option><option value="all">All statuses</option>${['not_started','in_progress','blocked','needs_review','passed','failed','not_applicable'].map((v)=>`<option value="${v}">${human(v)}</option>`).join('')}</select></label><label><span>Severity</span><select class="input" id="startupSeverity"><option value="all">All severities</option><option value="critical">Critical</option><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select></label><label><span>Section</span><select class="input" id="startupPhase">${phaseOptions(rows)}</select></label></section>
    <section class="startup-item-list">${shown.length?shown.map(card).join(''):`<div class="card startup-empty"><h2>${st.open===0&&state.filters.status==='open'?'All readiness gates are closed':'No readiness items match these filters'}</h2><p>${st.open===0&&state.filters.status==='open'?'Choose All statuses to review the completed gates.':'Clear the search or reset the status, severity, and section filters.'}</p><button class="btn" id="startupResetFilters" type="button">${st.open===0&&state.filters.status==='open'?'Show all statuses':'Reset filters'}</button></div>`}</section>
    <section class="card"><h2>Recent status history</h2><div class="table-wrap"><table class="admin-table"><thead><tr><th>Item</th><th>Change</th><th>Owner</th><th>Evidence</th><th>When</th></tr></thead><tbody>${(data.recent_history||[]).length?(data.recent_history||[]).slice(0,30).map((r)=>`<tr><td>${esc(r.item_title||r.item_key)}</td><td>${esc(human(r.previous_status))} → ${esc(human(r.next_status))}</td><td>${esc(r.owner_name||'—')}</td><td>${r.evidence_url?`<a href="${esc(r.evidence_url)}" target="_blank" rel="noopener">Open</a>`:esc(r.evidence_notes||'—')}</td><td>${esc(r.changed_at||'')}</td></tr>`).join(''):'<tr><td colspan="5">No saved status changes yet.</td></tr>'}</tbody></table></div></section>`; bind(); }
  function formPayload(form,key,action='save_item') { const payload=Object.fromEntries(new FormData(form).entries()); return {...payload,action,item_key:key}; }
  function saveLocal(payload) { state.local[payload.item_key]={item_status:payload.item_status||'not_started',owner_name:payload.owner_name||'',due_date:payload.due_date||'',evidence_url:payload.evidence_url||'',evidence_notes:payload.evidence_notes||'',blocked_reason:payload.blocked_reason||''}; writeLocal(); state.data=applyLocal(state.data||fallbackData()); render(); message('The server save failed. This change is stored only in this browser and is marked unsynced.', 'warning'); }
  async function submit(payload) { try { const data=await api(payload); delete state.local[payload.item_key]; writeLocal(); state.data=applyLocal(data); render(); message(data.message||'Startup readiness item saved.','success'); } catch(error) { if(Number(error.status||0)>=400&&Number(error.status||0)<500){ message(error.message||'Review the readiness information and try again.','error'); return; } saveLocal(payload); message(error.message||'Could not save to D1. Browser-only recovery was used.','warning'); } }
  function bind() {
    id('startupRefresh')?.addEventListener('click',load);
    id('startupResetFilters')?.addEventListener('click',()=>{state.filters={search:'',status:'all',severity:'all',phase:'all'};render();});
    id('startupExport')?.addEventListener('click',()=>{ const content=state.data?.markdown||'# Startup Readiness\n'; const blob=new Blob([content],{type:'text/markdown;charset=utf-8'}); const url=URL.createObjectURL(blob); const link=document.createElement('a'); link.href=url; link.download='DEVIL_N_DOVE_STARTUP_READINESS_STATUS.md'; document.body.appendChild(link); link.click(); link.remove(); setTimeout(()=>URL.revokeObjectURL(url),1200); });
    id('startupSync')?.addEventListener('click',syncLocal);
    const search=id('startupSearch'); if(search)search.oninput=()=>{state.filters.search=search.value;clearTimeout(state.filterTimer);state.filterTimer=setTimeout(()=>{render();const next=id('startupSearch');if(next){next.focus();next.setSelectionRange(next.value.length,next.value.length);}},180);};
    const status=id('startupStatus'); if(status){status.value=state.filters.status;status.onchange=()=>{state.filters.status=status.value;render();};}
    const severity=id('startupSeverity'); if(severity){severity.value=state.filters.severity;severity.onchange=()=>{state.filters.severity=severity.value;render();};}
    const phase=id('startupPhase'); if(phase){phase.value=state.filters.phase;phase.onchange=()=>{state.filters.phase=phase.value;render();};}
    document.querySelectorAll('.startup-item-form').forEach((form)=>{ const card=form.closest('[data-key]'); const key=card?.dataset.key||''; const statusSelect=form.elements.item_status; const blocked=form.querySelector('.blocked-field'); if(statusSelect)statusSelect.onchange=()=>{blocked.hidden=statusSelect.value!=='blocked';}; form.onsubmit=(event)=>{event.preventDefault();submit(formPayload(form,key));}; form.querySelector('[data-complete]')?.addEventListener('click',()=>{ const payload=formPayload(form,key,'mark_complete'); payload.item_status='passed'; submit(payload); }); form.querySelector('[data-reopen]')?.addEventListener('click',()=>{ const payload=formPayload(form,key,'reopen_item'); payload.item_status='in_progress'; submit(payload); }); });
  }
  async function syncLocal() { const entries=Object.entries(state.local); if(!entries.length)return; message(`Synchronizing ${entries.length} browser change${entries.length===1?'':'s'}…`); for(const [key,value] of entries){ try{await api({action:'save_item',item_key:key,...value});delete state.local[key];writeLocal();}catch(error){message(`Synchronization stopped at ${key}: ${error.message}`,'error');return;} } await load(); message('All browser-only changes were synchronized to D1.','success'); }
  async function load() { message('Loading startup readiness…'); try{const data=await api();state.data=applyLocal(data);render();message(data.degraded?(data.backend_warning||'Loaded in degraded mode.'):'Startup readiness loaded.',data.degraded?'warning':'success');}catch(error){state.data=applyLocal(fallbackData());render();message(error.message||'The startup service is unavailable. Instructions are shown with browser-only recovery.','warning');} }
  document.addEventListener('DOMContentLoaded',load);
})();
